let state=initialState(),storageLocked=false,rawBackup='',presentation=false,selectedDate=today(),calendarAnchor='',month=today().slice(0,7),tab='today',taskFilter='all',stageFilter='Все',contentArea='work',contentPlanDate=today(),factDate=today(),lastQuickEntry=null,lastFunnelEntry=null,search='',editorKind='',editId=null,noteTimer;
