function freeDay(d){return `<button class="diary-free-day" data-action="diary-day" data-date="${d}"><strong>${dateText(d,{weekday:'long'})}<span>${dateText(d)}</span></strong><span>${isRestDay(d)?'☾ Выходной':'Нет планов'} <b>＋</b></span></button>`;}
function renderToday(){const start=range==='month'?selectedDate.slice(0,7)+'-01':range==='week'||range==='fortnight'?mondayOf(selectedDate):selectedDate,count=range==='month'?new Date(Number(selectedDate.slice(0,4)),Number(selectedDate.slice(5,7)),0).getDate():{day:1,week:7,fortnight:14}[range],dates=Array.from({length:count},(_,i)=>addDays(start,i)),shown=range==='month'?dates.filter(d=>d===selectedDate||hasPlans(d)):dates;return heading('Расписание','Встречи, дела, платежи и контент — в одном дне.','add-task','Добавить')+dayPhraseCard()+weeklyFocusCard()+`<div class="agenda-controls"><div class="range-tabs">${[['day','День'],['week','Неделя'],['fortnight','14 дней'],['month','Месяц']].map(([id,label])=>`<button data-action="range" data-range="${id}" class="${range===id?'active':''}" aria-pressed="${range===id}">${label}</button>`).join('')}</div>${dateControls()}</div>${selectedDate===today()?reminderBlock():''}<div class="agenda-feed">${range==='month'||range==='fortnight'?dayCard(selectedDate,true):shown.map(d=>range!=='day'&&!hasPlans(d)?freeDay(d):dayCard(d,d===selectedDate)).join('')}</div>${!['month','fortnight'].includes(range)&&count>1&&shown.length<count?`<p class="quiet-days">На остальные дни этого периода пока ничего не назначено. Можно выбрать любую дату выше.</p>`:''}<div class="agenda-links"><a href="#tasks">Все задачи →</a><a href="#content">Банк идей и сценариев →</a></div><details class="daily-note"><summary>✎ Заметка на ${dateText(selectedDate)}</summary>${notePanel(selectedDate)}</details>`;}
