function contentCard(r){if(!Array.isArray(r.steps)||!r.steps.length)return materialCard(r);const completed=r.steps.filter(step=>state.tasks.find(t=>t.id===step.taskId)?.done).length;return `<article class="funnel-project panel"><div class="project-heading"><span class="badge teal">ВОРОНКА</span><span class="hint">${completed} из ${r.steps.length} шагов</span></div><h2>${e(r.title)}</h2><div class="funnel-route"><small>КУДА ВЕДЁМ</small><strong>${e(r.destination||r.funnel||'Маршрут уточним с Клодей')}</strong></div><div class="project-progress"><i style="width:${completed/r.steps.length*100}%"></i></div><div class="project-steps">${r.steps.map(step=>{const t=state.tasks.find(t=>t.id===step.taskId);return `<div class="compact-task ${t?.done?'done':''}">${t?`<button class="task-check ${t.done?'checked':''}" data-action="toggle-task" data-id="${e(t.id)}" aria-label="${t.done?'Вернуть':'Выполнить'}: ${e(step.title)}">${t.done?'✓':''}</button>`:'<span>◇</span>'}<span class="row-title">${e(step.title)}</span>${t?.date?`<small class="hint">${dateText(t.date)}</small>`:''}</div>`;}).join('')}</div><p class="hint">${r.steps.some(step=>state.tasks.find(t=>t.id===step.taskId)?.date)?'Шаги с датой также видны в расписании.':'Без сроков · даты можно наговорить Клоде позже.'}</p></article>`;}
function materialCard(r){const cover=r.cover||(r.id==='demo-c1'?'slide':r.id==='demo-c2'?'robot':r.id==='demo-c3'?'portrait':'none');return `<article class="content-card" data-stage="${e(r.stage)}"><button class="content-art ${e(cover)}" data-action="edit-content" data-id="${e(r.id)}" aria-label="Открыть материал: ${e(r.title)}">${coverPaths[cover]?`<img src="${coverPaths[cover]}" alt="Фирменная обложка материала">`:`<span>${e(r.format)}</span><i aria-hidden="true">✦</i>`}<span class="art-stage">${e(r.stage)}</span></button><div class="content-inner"><div class="row-meta" style="margin:0"><span class="badge teal">${e(r.format)}</span><span>${e(r.channel)}</span></div><h3><button class="row-link" data-action="edit-content" data-id="${e(r.id)}">${e(r.title)}</button></h3><p>${e(r.note||'Добавь сценарий, тезисы или заметку к материалу.')}</p>${r.funnel||r.codeword||r.destination?`<div class="funnel-route"><small>МАРШРУТ МАТЕРИАЛА</small>${r.funnel?`<strong>↗ ${e(r.funnel)}</strong>`:''}${r.codeword?`<span>Кодовое слово: <b>${e(r.codeword)}</b></span>`:''}${r.destination?`<span>→ ${e(r.destination)}</span>`:''}</div>`:''}<div class="row-meta">${r.date?`<span>${dateText(r.date)}</span>`:'<span>Без даты</span>'}${safeUrl(r.link)?`<a href="${e(safeUrl(r.link))}" target="_blank" rel="noopener">Материал ↗</a>`:''}</div></div><div class="content-bottom"><select data-content-stage="${e(r.id)}" aria-label="Этап: ${e(r.title)}">${STAGES.map(s=>`<option ${s===r.stage?'selected':''}>${s}</option>`).join('')}</select><button class="text-button" data-action="edit-content" data-id="${e(r.id)}">Открыть →</button></div></article>`;}
function contentIntro(){return `<section class="content-illustrated-intro"><figure><img src="assets/clodya-content-hero.png" alt="Клодя собирает карточки видео, календаря и воронки" width="1536" height="1024"></figure><div><span class="goal-caption">ТВОЯ ПРАВАЯ РУКА · КЛОДЯ</span><h2>Идея голосом.<br>План — перед тобой.</h2><p>Расскажи, что хочешь сделать. Сохраним воронку, разложим на шаги и назначим дни, когда ты будешь готова.</p><button class="primary" data-action="voice">🎙 Наговорить Клоде</button></div></section>`;}
function contentGoalBoard(){if(presentation)return '<p class="hint">Личный план скрыт в режиме записи.</p>';const metrics=contentMetrics(state,today());if(!metrics)return '<p class="hint">План на этот месяц пока не задан. Наговори его Клоде.</p>';const g=metrics.goal,from=g.planningFrom||addDays(today(),1),last=addDays(g.goalMonth+'-01',new Date(Number(g.goalMonth.slice(0,4)),Number(g.goalMonth.slice(5,7)),0).getDate()-1),days=from<=last?workingDays(from,last,g.weeklyRestDays||[0],g.restDays||[]):0,extra=Math.max(0,g.reelsTarget-days),doubles=Math.min(days,extra);return `<section class="content-goal-board compact-goals"><div class="goal-board-top"><h2>План на ${dateText(g.goalMonth+'-01',{month:'long'})}</h2><span class="badge teal">Публикации</span></div><div class="publication-tiers">${[[1,'👏 Базовый минимум'],[2,'⭐ Оптимум'],[3,'🏆 Максимум']].map(([n,label])=>`<div><span>${label}</span><strong>${n}</strong><small>Reels в день</small></div>`).join('')}</div><div class="goal-plan-targets"><div><span>Reels · опубликовано</span><strong>${g.reelsTarget} <small>в месяц</small></strong><small>Ориентир: ${Number(g.weeklyReels)||5} в неделю</small></div><div><span>Воронки · запуски</span><strong>${g.funnelsTarget} <small>в месяц</small></strong><small>${Number(g.weeklyFunnels)||3} в неделю</small></div></div><div class="carousel-stretch"><span>✦ СУПЕР-ПЛАН</span><strong>${Number(g.monthlyCarousels)||4} карусели в месяц · ${Number(g.weeklyCarousels)||1} в неделю</strong><small>Дополнительно</small></div><div class="capacity-strip"><strong>${dateText(from)} — ${dateText(last)} · ${days} рабочих дней</strong><span>${extra>days?'Для этой цели нужен пересмотр дневного темпа':extra?`По одному Reels в каждый рабочий день. В ${doubles} из этих дней — ещё по одному Reels.`:`Для цели достаточно ${g.reelsTarget} рабочих дней с одним Reels в день.`}</span><small>Суббота — рабочий день. Воскресенье — выходной. Дополнительный выходной можно отметить в разделе «Факт» или сообщить Клоде голосом. Недельные ориентиры выше — для плана на 4 недели.</small></div><div class="plan-rules"><span>◷ Сценарий, съёмка, монтаж — подготовка</span><span>✓ Выложенные обычные и пробные — публикации</span><span>☾ Выходной — без дневного норматива</span></div></section>`;}
function contentFactBoard(){if(presentation)return '<p class="hint">Личные результаты скрыты в режиме записи.</p>';const m=contentMetrics(state,factDate);if(!m)return '<p class="hint">План на этот месяц пока не задан.</p>';const g=m.goal,left=Math.max(0,g.reelsTarget-m.published),pct=Math.min(100,Math.round(m.published/g.reelsTarget*100)),weekGap=Math.max(0,(g.weeklyFunnels||3)-m.launchedWeek),dates=Array.from({length:7},(_,i)=>addDays(factDate,i-6)),counts=dates.map(d=>state.content.filter(r=>r.format==='Reels'&&r.stage==='Опубликовано'&&(r.publishedDate||r.date)===d).length),max=Math.max(3,...counts);return `<section class="content-goal-board compact-goals"><div class="goal-board-top"><h2>Факт на ${dateText(factDate)}</h2><span class="badge warm">Личное</span></div>${contentSuccessBars(m)}<div class="fact-controls"><label>Отметить за дату<input type="date" id="fact-date" value="${factDate}" min="${g.goalMonth}-01" max="${addDays(g.goalMonth+'-01',new Date(Number(g.goalMonth.slice(0,4)),Number(g.goalMonth.slice(5,7)),0).getDate()-1)}"></label><div class="fact-entry-buttons"><button class="primary" data-action="quick-reel" data-mode="ordinary" ${factDate>today()?'disabled':''}>＋ Обычный Reels</button><button class="quiet" data-action="quick-reel" data-mode="trial" ${factDate>today()?'disabled':''}>＋ Пробный Reels</button><button class="quiet" data-action="quick-carousel" ${factDate>today()?'disabled':''}>＋ Карусель</button><button class="quiet ${m.rest?'rest-active':''}" data-action="toggle-rest" aria-pressed="${m.rest}" ${(g.weeklyRestDays||[0]).includes(new Date(factDate+'T12:00:00Z').getUTCDay())?'disabled':''}>☾ ${m.rest?'Выходной отмечен':'Отметить выходной'}</button></div><small>Одно нажатие — одна публикация. Голосом — в обычном чате Клоди.</small>${factEntries(state,factDate).some(r=>!r.factCancelled)?'<button class="quiet" data-action="cancel-last-fact">↶ Отменить последнюю отметку</button>':''}</div>${funnelFactControls()}${factHistoryList()}<div class="goal-work-grid"><div><span>Опубликовано</span><strong>${m.published} <small>из ${g.reelsTarget}</small></strong><p>Обычные: ${m.ordinary} · пробные: ${m.trial}</p></div><div><span>Подготовка</span><strong>${m.preparation}</strong><p>Сценарий / съёмка / монтаж</p></div><div><span>Воронки за месяц</span><strong>${m.launched} <small>из ${g.funnelsTarget}</small></strong><p>За неделю: ${m.launchedWeek} из ${Number(g.weeklyFunnels)||3}</p></div></div><div class="goal-ready-caption"><span>Месячная цель</span><b>${pct}%</b></div><div class="project-progress"><i style="width:${pct}%"></i></div><div class="carousel-stretch"><span>✦ СУПЕР-ПЛАН · КАРУСЕЛИ</span><strong>${m.carouselsMonth} из ${Number(g.monthlyCarousels)||4} за месяц</strong><small>За неделю: ${m.carouselsWeek} из ${Number(g.weeklyCarousels)||1} · отдельно от Reels</small></div><div class="fact-gap"><strong>Осталось: ${left} публикаций</strong><span>До недельной цели: ${weekGap} запуска воронки</span></div><h3 class="fact-chart-title">Публикации · последние 7 дней</h3><div class="fact-chart">${dates.map((d,i)=>`<div><b>${counts[i]}</b><div class="fact-bar-track"><i style="height:${counts[i]/max*100}%"></i></div><small>${Number(d.slice(-2))}.${d.slice(5,7)}</small></div>`).join('')}</div><div class="daily-output-status"><strong>${m.daily?publicationAward(m.daily).icon:m.rest?'☾':'◷'} ${e(m.daily?publicationAward(m.daily).label:m.status)}</strong><span>За выбранный день опубликовано: ${m.daily}</span></div><p class="hint fact-note">Учитываются только отмеченные публикации. Подготовка в число опубликованных не входит.</p></section>`;}

function contentCards(){const records=state.content.filter(r=>!r.goalType&&!(r.quickEntry&&r.factCancelled)&&(stageFilter==='Все'||r.stage===stageFilter)&&(`${r.title} ${r.note} ${r.funnel||''} ${r.destination||''}`).toLowerCase().includes(search.toLowerCase()));return records.length?`<div class="content-grid">${records.map(contentCard).join('')}</div>`:`<div class="full-empty">${empty(state.content.length?'Ничего не нашлось':'От идеи — к публикации',state.content.length?'Попробуй другой этап или запрос.':'Отправь Клоде голосовое: что придумала и что нужно сделать. План появится здесь.','voice','🎙 Наговорить идею')}</div>`;}
function reminderFields(kind,r){const value=r.remindAt?new Date(Date.parse(r.remindAt)+25200000).toISOString().slice(0,16):'';return `<label class="checkbox-field"><input type="checkbox" name="notify" ${r.notify!==false?'checked':''}>Напоминать в Telegram</label>${kind==='event'?field('remindMinutes','За сколько минут до встречи','number',r.remindMinutes??60,'min="0" max="43200" required'):''}${field('remindAt','Или точное время напоминания · Барнаул','datetime-local',value)}<p class="hint">${kind==='task'?'Без точного времени: в 09:00 в день задачи.':kind==='event'?'Без точного времени: за указанное число минут.':'Без точного времени: за выбранное число дней и в день оплаты в 09:00.'} Прошедшие напоминания не отправляются задним числом.</p>`;}
function receiveCloud(next){const el=$('#day-note');if($('#editor').open||(el&&el.value!==(state.notes[el.dataset.date]||'')))return false;state=validateState(next);localStorage.setItem(KEY,JSON.stringify(state));if(cloudReady)render();return true;}
function syncStatus(info){const label=$('#storage-label');if(label)label.textContent=info.message;$('#save-status').textContent=info.message;const banner=$('#sync-banner');if(!banner)return;banner.hidden=['saved','loading'].includes(info.kind);banner.innerHTML=`${e(info.message)} ${info.kind==='conflict'?'<button class="text-button" data-action="resolve-cloud">Загрузить серверную версию</button>':''}`;}
async function startCloud(){cloudError='';render();try{cloud=cloud||new PlannerSync({key:KEY,onState:receiveCloud,onStatus:syncStatus});const next=await cloud.connect(state);state=validateState(next);localStorage.setItem(KEY,JSON.stringify(state));cloudReady=true;render();if(tab==='payments'&&financeTab==='sales')loadSales();}catch(err){cloudError=err.message;cloudReady=false;render();}}
route();if(!demo)startCloud();

function demoRub(n){return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';}
function purchaseWord(n){const x=n%100,y=n%10;return x>=11&&x<=14?'покупок':y===1?'покупка':y>=2&&y<=4?'покупки':'покупок';}
function demoProducts(){const g=state.content.find(r=>r.goalType==='content-output'&&r.goalMonth===today().slice(0,7));return [{id:'1',title:'Подружись с Claude + ChatGPT',label:'ПЕРВАЯ СТУПЕНЬ',price:1490,count:demoSaleCount,goal:500000,targetRub:Number(g?.salesTargetFirst)||500000,targets:[25,50,100]},{id:'2',title:'Вайбкодинг с Claude + ChatGPT',label:'ВТОРАЯ СТУПЕНЬ',price:49900,count:demoSaleCount2,goal:500000,targetRub:Number(g?.salesTargetSecond)||500000,targets:[25,50,100]}];}
function demoProductCard(p){const amount=p.count*p.price,pct=Math.round(amount/p.targetRub*1000)/10,targetCount=Math.ceil(p.targetRub/p.price);return `<section class="sales-studio stage-${p.id}"><div class="sales-product"><div><span class="sales-pill">${p.label}</span><h2>${e(p.title)}</h2><p>Стоимость участия · <b>${e(demoRub(p.price))}</b></p></div><div class="sales-goal-ring" style="--fill:${Math.min(pct,100)}%"><span><strong>${pct}%</strong><small>к плану</small></span></div></div><div class="sales-counter-label">ПОКУПКИ ЗА МЕСЯЦ · ДЕМО</div><div class="sales-counter"><button class="sales-step" data-action="demo-sale" data-product="${p.id}" data-delta="-1" aria-label="Уменьшить покупки ступени ${p.id}" ${p.count===0?'disabled':''}>−</button><div><strong>${p.count} <small>из ${targetCount}</small></strong><span>продаж за месяц</span></div><button class="sales-step orange" data-action="demo-sale" data-product="${p.id}" data-delta="1" aria-label="Добавить покупку ступени ${p.id}" ${p.count===30?'disabled':''}>＋</button></div><div class="sales-revenue"><small>СУММА ОПЛАТ · СТУПЕНЬ ${p.id}</small><strong>${e(demoRub(amount))}</strong><span>${p.count} × ${e(demoRub(p.price))} <i>· без вычета расходов</i></span></div><div class="sales-target-head"><span>План на месяц</span><b>${e(demoRub(p.targetRub))}<small>${targetCount} продаж при чеке ${e(demoRub(p.price))}</small></b></div><div class="sales-target-track"><i style="width:${Math.min(pct,100)}%"></i></div><div class="sales-milestones">${p.targets.map(n=>`<div class="${amount>=p.targetRub*n/100?'achieved':''}"><span>${n===100?'Цель':n+'% плана'}</span><strong>${e(demoRub(p.targetRub*n/100))}</strong><small>${amount>=p.targetRub*n/100?'Достигнуто ✓':'План на месяц'}</small></div>`).join('')}</div><div class="sales-encourage"><span>${amount>=p.targetRub?'✧':'✦'}</span><div><strong>${amount>=p.targetRub?'Месячный план выполнен!':'До плана '+demoRub(p.targetRub-amount)}</strong><p>Покупки — демо. План — 500 000 ₽ на ступень.</p></div></div></section>`;}
function demoSales(){const products=demoProducts(),total=products.reduce((sum,p)=>sum+p.count*p.price,0);return `<div class="sales-demo-label">ДЕМО · ПОКУПКИ ВЫМЫШЛЕННЫЕ</div><section class="sales-overview"><div class="sales-overview-copy"><span>ОБЕ СТУПЕНИ · ПРИМЕР</span><strong>${e(demoRub(total))}</strong><small>${demoSaleCount+demoSaleCount2} ${purchaseWord(demoSaleCount+demoSaleCount2)} · сумма оплат</small><small>Общий план на месяц: ${e(demoRub(products.reduce((sum,p)=>sum+p.targetRub,0)))}</small></div><div class="sales-overview-breakdown">${products.map(p=>`<span><small>Ступень ${p.id}</small><b>${e(demoRub(p.count*p.price))}</b><small>из ${e(demoRub(p.targetRub))}</small></span>`).join('')}</div><span class="sales-overview-spark" aria-hidden="true">✦</span></section>${salesQuantitySummary(products)}<div class="sales-stage-tabs">${[['all','Обе ступени'],['1','Ступень 1'],['2','Ступень 2']].map(([id,label])=>`<button data-action="demo-stage" data-stage="${id}" class="${demoSalesStage===id?'active':''}" aria-pressed="${demoSalesStage===id}">${label}</button>`).join('')}</div><div class="sales-products">${products.filter(p=>demoSalesStage==='all'||demoSalesStage===p.id).map(demoProductCard).join('')}</div><section class="sales-receipts"><div><h3>Лента оплат · пример</h3><span>Раздельно по ступеням</span></div>${products.filter(p=>demoSalesStage==='all'||demoSalesStage===p.id).map(p=>Array.from({length:Math.min(p.count,3)},(_,i)=>`<article><span class="receipt-icon ${p.id==='2'?'receipt-premium':''}">✓</span><div><b>Ступень ${p.id} · ${p.id==='1'?'Подружись':'Вайбкодинг'}</b><small>Пример покупки ${i+1}</small></div><strong>+${e(demoRub(p.price))}</strong></article>`).join('')).join('')}${!demoSaleCount&&!demoSaleCount2?'<p class="hint">В примере пока нет покупок.</p>':''}</section><p class="sales-auto-note">↻ Кнопки +/− меняют только демо. Демо не связано с платёжной системой. Сумма оплат показана без вычета расходов, комиссий и возвратов.</p>`;}

function realSales(){
 const targets=demoProducts().map(p=>p.targetRub),m=salesProgress(salesData,targets);
 if(!m)return '<p class="hint">Получен общий отчёт. Ждём разбивку по ступеням для расчёта плана.</p>';
 const rub=n=>e(demoRub(n)),pct=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);
 return `<section class="sales-overview"><div class="sales-overview-copy"><span>ДВЕ СТУПЕНИ · ФАКТ ЗА МЕСЯЦ</span><strong>${rub(m.amount)}</strong><small>из ${rub(m.target)} · ${pct(m.pct)}% плана</small></div><div class="sales-overview-breakdown"><span><small>Сегодня</small><b>${rub(m.todayAmount)}</b><small>${m.todayCount} ${purchaseWord(m.todayCount)}</small></span><span><small>Осталось до цели</small><b>${rub(m.remaining)}</b><small>за этот месяц</small></span></div><span class="sales-overview-spark" aria-hidden="true">✦</span></section>${salesQuantitySummary(m.products)}<div class="sales-target-head"><span>Общий план на месяц</span><b>${rub(m.target)}</b></div><div class="sales-target-track"><i style="width:${m.fill}%"></i></div><div class="sales-products">${m.products.map(p=>`<section class="sales-studio stage-${p.id}"><div class="sales-product"><div><span class="sales-pill">${p.label}</span><h2>${e(p.title)}</h2></div><div class="sales-goal-ring" style="--fill:${p.fill}%"><span><strong>${pct(p.pct)}%</strong><small>к плану</small></span></div></div><div class="sales-counter-label">ПОДТВЕРЖДЁННЫЕ ПОКУПКИ ЗА МЕСЯЦ</div><div class="sales-real-counter"><strong>${p.count} <small>из ${p.targetCount}</small></strong><span>продаж за месяц</span></div><div class="sales-revenue"><small>СУММА ОПЛАТ · СТУПЕНЬ ${p.id}</small><strong>${rub(p.amount)}</strong><span>Сегодня: ${rub(p.today.amountRub)} · ${p.today.count} ${purchaseWord(p.today.count)}</span></div><div class="sales-target-head"><span>План на месяц</span><b>${rub(p.target)}<small>${p.targetCount} продаж при чеке ${rub(p.price)}</small></b></div><div class="sales-target-track"><i style="width:${p.fill}%"></i></div><div class="sales-milestones">${[25,50,100].map(n=>`<div class="${p.pct>=n?'achieved':''}"><span>${n===100?'Цель':n+'% плана'}</span><strong>${rub(p.target*n/100)}</strong><small>${p.pct>=n?'Достигнуто ✓':'Впереди'}</small></div>`).join('')}</div><div class="sales-encourage"><span>✦</span><div><strong>${p.remaining?'До плана '+rub(p.remaining):'Месячный план выполнен!'}</strong><p>${p.count?'Каждая подтверждённая покупка отражается в прогрессе.':'Ждём первую подтверждённую покупку.'} Количество продаж рассчитано по полному чеку и округлено вверх.</p></div></div></section>`).join('')}</div>${m.unassigned?`<p class="hint">${m.unassigned} оплат не относятся к этим двум ступеням или пока не распределены; в прогресс ступеней они не включены.</p>`:''}`;
}

function weeklyFunnelFocus(){
 const m=contentMetrics(state,today());if(!m)return '';
 const target=Number(m.goal.weeklyFunnels)||3,left=Math.max(0,target-m.launchedWeek),project=state.content.find(r=>Array.isArray(r.steps)&&r.stage!=='Опубликовано'),step=project?.steps.find(r=>!state.tasks.find(t=>t.id===r.taskId)?.done);
 const prompt=!left?'Недельная цель выполнена!':m.launchedWeek===0?'Начнём с первой воронки.':left===1?'До недельной цели осталась одна воронка.':'Первая воронка готова. Переходим к следующей.';
 return `<section class="weekly-funnel-focus"><div><small>ВОРОНКИ ЭТОЙ НЕДЕЛИ</small><strong>${m.launchedWeek} <span>из ${target} запущено</span></strong></div><div class="funnel-week-markers">${Array.from({length:target},(_,i)=>`<span class="${i<m.launchedWeek?'achieved':i===m.launchedWeek?'next':''}">${i<m.launchedWeek?'✓':i+1}</span>`).join('')}</div><p>${prompt}</p>${left&&step?`<small>Ближайший шаг: <b>${e(step.title)}</b></small>`:''}</section>`;
}

function calendarControls(){
 const monthMode=range==='month',anchor=calendarAnchor||(monthMode?selectedDate.slice(0,7)+'-01':mondayOf(selectedDate)),count=monthMode?new Date(Number(anchor.slice(0,4)),Number(anchor.slice(5,7)),0).getDate():14,offset=monthMode?(new Date(anchor+'T12:00:00Z').getUTCDay()+6)%7:0,dates=Array.from({length:count},(_,i)=>addDays(anchor,i));
 const label=monthMode?dateText(anchor,{month:'long',year:'numeric'}):dateText(anchor)+' — '+dateText(addDays(anchor,13));
 return `<section class="calendar-selector"><div class="calendar-selector-head"><button class="quiet" data-action="calendar-prev" aria-label="Предыдущий период">←</button><strong>${label}</strong><button class="quiet" data-action="calendar-next" aria-label="Следующий период">→</button><button class="text-button" data-action="today">Сегодня</button></div><div class="calendar-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-date-grid">${'<span class="calendar-spacer"></span>'.repeat(offset)}${dates.map(d=>{const plans=hasPlans(d),pay=!presentation&&paymentsInMonth(state.payments,d.slice(0,7)).some(p=>p.due===d);return `<button class="calendar-date ${d===selectedDate?'selected':''} ${d===today()?'today':''}" data-action="calendar-select" data-date="${d}" aria-label="${dateText(d)}${pay?' — платёж':plans?' — есть планы':''}" aria-pressed="${d===selectedDate}"><span>${Number(d.slice(-2))}</span><i>${pay?'🏦':plans?'●':''}</i></button>`}).join('')}</div><div class="calendar-selector-foot"><span>● Есть планы · 🏦 Платёж</span><label class="date-picker-label">К дате <input type="date" id="schedule-date" value="${selectedDate}" aria-label="Выбрать другую дату"></label></div></section>`;
}
setInterval(()=>{if(tab==='payments'&&financeTab==='sales'&&cloudReady&&!document.hidden)loadSales();},60000);

function salesQuantitySummary(products){return `<div class="sales-quantity-summary">${products.map(p=>`<div><small>Ступень ${e(p.id)} · продажи за месяц</small><strong>${p.count} <span>из ${p.targetCount||Math.ceil(p.targetRub/p.price)}</span></strong><small>Цель ${e(demoRub(p.target||p.targetRub))} · чек ${e(demoRub(p.price))}</small></div>`).join('')}</div>`;}

function resizeEditorViewport(){document.documentElement.style.setProperty('--editor-viewport-height',Math.round(window.visualViewport?.height||innerHeight)+'px');}
window.visualViewport?.addEventListener('resize',resizeEditorViewport);window.addEventListener('resize',resizeEditorViewport);
function contentItemsOn(day){
 const tasks=state.tasks.filter(t=>t.date===day&&t.category==='work'&&(t.contentId||t.deliverableType==='reel'||/reels|рилс|карусел/i.test(t.title))).map(t=>({title:t.title,mark:/карусел/i.test(t.title)?'H':t.deliverableType==='reel'||/reels|рилс/i.test(t.title)?'R':'◇',done:t.done}));
 const materials=state.content.filter(c=>!c.goalType&&!c.factCancelled&&c.date===day&&['Reels','Карусель'].includes(c.format)).map(c=>({title:c.title,mark:c.format==='Reels'?'R':'H',done:c.stage==='Опубликовано'}));return [...tasks,...materials];
}
function contentPlanCalendar(){
 const m=contentMetrics(state,today());if(!m)return '<p class="hint">План на месяц пока не задан.</p>';const g=m.goal,first=g.goalMonth+'-01',count=new Date(Number(g.goalMonth.slice(0,4)),Number(g.goalMonth.slice(5,7)),0).getDate(),last=addDays(first,count-1),offset=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7;
 if(!contentPlanDate.startsWith(g.goalMonth))contentPlanDate=first;const items=contentItemsOn(contentPlanDate);
 return `<section class="content-plan-calendar panel"><div class="panel-title"><h2>План на ${dateText(first,{month:'long'})}</h2></div><div class="content-calendar-targets"><span><b>R · ${g.reelsTarget}</b> в месяц · ${g.weeklyReels||5} в неделю</span><span><b>H · ${g.monthlyCarousels||4}</b> в месяц · ${g.weeklyCarousels||1} в неделю</span></div><p class="hint">Воронки: ${g.funnelsTarget} в месяц · ${g.weeklyFunnels||3} в неделю</p><div class="calendar-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-date-grid">${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const day=addDays(first,i),rows=contentItemsOn(day),markers=['R','H'].filter(mark=>rows.some(r=>r.mark===mark));return `<button class="calendar-date ${day===contentPlanDate?'selected':''} ${day===today()?'today':''}" data-action="content-plan-day" data-date="${day}" aria-label="Контент на ${dateText(day)}" aria-pressed="${day===contentPlanDate}"><span>${i+1}</span><i>${markers.join(' · ')|| (rows.length?'●':'')}</i></button>`}).join('')}</div><div class="calendar-selector-foot"><span>R — работа с Reels · H — карусель</span><input type="date" id="content-plan-date" min="${first}" max="${last}" value="${contentPlanDate}" aria-label="Дата плана контента"></div><div class="content-planned-day"><h3>${dateText(contentPlanDate)}</h3>${items.length?items.map(item=>`<p class="${item.done?'done':''}"><b>${item.mark}</b><span>${e(item.title)}</span>${item.done?'<small>✓</small>':''}</p>`).join(''):'<p class="hint">На эту дату контент ещё не назначен.</p>'}</div></section>${adaptivePlanCard()}<details class="content-plan-details"><summary>Цели, ориентиры и темп работы</summary>${weeklyFunnelFocus()}${contentGoalBoard()}</details>`;
}

function funnelFactControls(){const available=state.content.filter(r=>Array.isArray(r.steps)&&r.stage!=='Опубликовано');return `<div class="funnel-fact-controls"><strong>Воронка готова и работает?</strong>${available.length?`<label>Что запустила<select id="fact-funnel">${available.map(r=>`<option value="${e(r.id)}">${e(r.title)}</option>`).join('')}</select></label><button class="primary" data-action="quick-funnel" ${factDate>today()?'disabled':''}>＋ Воронка запущена</button>`:'<p class="hint">Все добавленные воронки уже отмечены запущенными. Новую можно наговорить Клоде.</p>'}</div>`;}

function adaptivePlanCard(){const p=adaptivePlan(state,today());if(!p||presentation)return '';return `<section class="adaptive-plan panel"><div class="panel-title"><h2>Гибкий темп</h2><span class="badge teal">Осталось ${p.remaining} Reels за месяц</span></div><div class="reward-ladder"><span>👏 1 · минимум</span><span>⭐ 2 · оптимум</span><span>🏆 3 · максимум</span></div>${p.remaining?`<p>До ближайшего выходного: ещё <b>${p.needed} публикаций</b></p><div class="adaptive-days">${p.days.map(d=>`<div><span>${dateText(d.date,{weekday:'short',day:'numeric'})}</span><strong>${d.count?'+ '+d.count:'✓'}</strong><small>${d.published?'Уже опубликовано: '+d.published:'Reels'}</small></div>`).join('')}</div>${p.shortfall?`<p class="hint">В темп до 3 Reels в день не помещаются ещё ${p.shortfall}. Пересмотрим цель или перенесём часть на следующую неделю.</p>`:''}<small>Рекомендация пересчитывается после публикаций и отметки выходного. Даты задач остаются твоим выбором.</small>`:'<p>🏆 Месячная цель выполнена!</p>'}</section>`;}

function contentSuccessBars(m){const rows=[['Reels',m.published,Number(m.goal.reelsTarget)||20],['Воронки',m.launched,Number(m.goal.funnelsTarget)||12],['Карусели',m.carouselsMonth,Number(m.goal.monthlyCarousels)||4]];return `<section class="content-success"><h3>Мой прогресс за месяц</h3>${rows.map(([title,count,target])=>`<div class="success-row"><span>${title}</span><strong>${count} из ${target} <small>· ${Math.round(count/target*100)}%</small></strong><div class="project-progress" role="progressbar" aria-label="${title}: ${count} из ${target}" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${Math.max(target,count)}"><i style="width:${Math.min(100,count/target*100)}%"></i></div></div>`).join('')}</section>`;}

function factHistoryList(){const rows=factEntries(state,factDate);return `<section class="fact-history"><h3>Отметки за ${dateText(factDate)}</h3>${rows.length?rows.map(r=>`<div class="fact-history-row ${r.factCancelled?'cancelled':''}"><span><b>${e(Array.isArray(r.steps)?'Воронка':r.format==='Карусель'?'Карусель':r.publicationMode==='trial'?'Пробный Reels':'Обычный Reels')}</b><small>${e(r.title)}${r.factCancelled?' · отменено':''}</small></span><button class="quiet" data-action="${r.factCancelled?'restore-fact':'cancel-fact'}" data-id="${e(r.id)}">${r.factCancelled?'Вернуть':'↶ Отменить'}</button></div>`).join(''):'<p class="hint">Пока нет отметок.</p>'}</section>`;}
